import React from 'react';
// Original user-supplied mark, embedded locally for both surfaces.
export function HeaderMark({size=48}){return <span className="fti-hologram" style={{width:size,height:size}} aria-hidden="true"><svg className="fti-brand-mark fti-header-mark" width={size} height={size} viewBox="170 170 914 914" aria-hidden="true" focusable="false"><image width="1254" height="1254" href="data:image/jpeg;base64,"/></svg></span>}
